304	func (pm *PathModel) handlePaste(msg tea.PasteMsg) (*PathModel, tea.Cmd) {
305		if pm.state != pathEditing || pm.pickerOpen() {
306			return pm, nil // a paste reaches the focused field only (Rule 111)
307		}
308		return pm.updateInput(msg)
309	}
310	
311	// updateInput hands msg to the field; a changed value drops the stale error.
312	func (pm *PathModel) updateInput(msg tea.Msg) (*PathModel, tea.Cmd) {
313		before := pm.input.Value()
314		var cmd tea.Cmd
315		pm.input, cmd = pm.input.Update(msg)
316		if pm.input.Value() != before {
317			pm.errText = ""
318		}
319		return pm, cmd
320	}
321	
322	func (pm *PathModel) launchFromInput() (*PathModel, tea.Cmd) {
323		tg, err := parsePathTarget(pm.input.Value())
324		if err != nil {
325			return pm, pm.footer.Error(capitalize(err.Error()))
326		}
327		return pm.launch(tg)
328	}
329	
330	// launch starts a run: the model changes here, in Update; the Cmd only does I/O.
331	func (pm *PathModel) launch(tg pathTarget) (*PathModel, tea.Cmd) {
332		if a := pm.launchable(); !a.Enabled() {
333			return pm, pm.footer.Warn(a.Reason)
334		}
335		pm.releaseRun()
336		pm.gen++
337		pm.target = tg
338		pm.clearRun()
339		pm.footer.Clear()
340	
341		ctx, cancel := context.WithCancel(context.Background())
342		ch := make(chan tea.Msg, pathChanCap)
343		pm.cancel, pm.msgs = cancel, ch
344		pm.input.Blur()
345		pm.state = pathRunning
346		return pm, startPathRun(ctx, pm.gen, tg, pm.source, pm.resolveTimeout, pm.engine, ch)
347	}
348	
349	// cancelRun answers esc at once: the run's late messages are dropped by the
350	// generation bump, the hops already seen stay on screen.
351	func (pm *PathModel) cancelRun() (*PathModel, tea.Cmd) {
352		pm.releaseRun()
353		pm.gen++
354		pm.result = &nettrace.Result{Outcome: nettrace.OutcomeCancelled}
355		pm.state = pathDone
356		return pm, nil
357	}
358	
359	// startPathRun builds the launch Cmd from values only, so that no closure
360	// reads the model (Rule 110).
361	func startPathRun(ctx context.Context, gen int, tg pathTarget, src pathSource, timeout time.Duration, e pathEngine, ch chan tea.Msg) tea.Cmd {
362		return tea.Batch(
363			func() tea.Msg {
364				producePath(ctx, gen, tg, src, timeout, e, ch)
365				return nil
366			},
367			waitForPathMsg(ch),
368		)
369	}
